css='''
:root{--ink:#252b27;--muted:#606b60;--coral:#cf4e39;--paper:#f8f7f3;--line:#deded7}
*{box-sizing:border-box}body{background:var(--paper);color:var(--ink);font:16px/1.6 system-ui,sans-serif;margin:0}
main{max-width:1180px;margin:auto;padding:42px 32px 70px}h1{font-size:44px;line-height:1.15;margin:12px 0 18px}h2{font-size:29px;margin:38px 0 16px}h3{margin:24px 0 8px}a{color:#9f3929}p{margin:12px 0}small,.muted{color:var(--muted)}
.eyebrow{color:var(--coral);letter-spacing:2px;font-size:12px;font-weight:700}.notice{padding:20px;border:1px solid #dab4a6;border-left:5px solid var(--coral);border-radius:10px;background:#fff3ec}
.stats,.flow{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:24px 0}.stat,.node{background:white;border:1px solid var(--line);padding:16px;border-radius:10px}.stat b{display:block;font-size:30px}.node b{display:block}.node small{display:block;margin-top:8px}
nav{display:flex;flex-wrap:wrap;gap:16px;margin:24px 0}table{width:100%;border-collapse:collapse;font-size:14px;background:white;margin:16px 0}th,td{padding:12px;text-align:left;border:1px solid var(--line);vertical-align:top}th{background:#eaece5}td:first-child{font-weight:650}figure{margin:24px 0;background:white;padding:14px;border:1px solid var(--line);border-radius:10px}figure img{max-width:100%;height:auto;display:block;margin:auto}figcaption{font-size:13px;margin-top:10px;color:var(--muted)}.screen img{max-height:660px}.draft img{max-height:850px}.icons img{max-height:380px}code{background:#eaece5;padding:2px 5px;border-radius:4px}li{margin:6px 0}details{border:1px solid var(--line);background:white;border-radius:8px;padding:12px;margin:12px 0}summary{cursor:pointer;font-weight:650}.ok{color:#316449}.partial{color:#a26120}
@media(max-width:800px){main{padding:24px 16px}h1{font-size:34px}.stats,.flow{grid-template-columns:repeat(2,1fr)}table{font-size:12px}th,td{padding:8px}}
@page{size:A4;margin:15mm}@media print{body{background:white;font-size:10pt}main{padding:0;max-width:none}h1{font-size:30pt}h2{font-size:20pt}nav,.web-only{display:none}.stats{gap:6px}.stat{padding:10px}.stat b{font-size:20pt}.flow{grid-template-columns:repeat(2,1fr)}table{font-size:8.5pt}th,td{padding:6px}tr{break-inside:avoid}figure{break-inside:avoid;padding:8px}.screen img{max-height:170mm}.draft{break-before:page}.draft img{max-height:210mm}.icons img{max-height:85mm}h2,h3{break-after:avoid}a{color:inherit;text-decoration:none}details{break-inside:avoid}}
'''
parts=['<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Folio 0.2.0 · Avance comprobado</title><style>'+css+'</style><main><span class="eyebrow">FOLIO · WINDOWS 10/11 X64 · 03 OCT 2026</span><h1>Una base que ya guarda<br>comentarios PDF reales.</h1><p>Entrega de desarrollo 0.2.0. Se conserva la lectura útil del visor y se reemplaza la exportación de gráficos por comentarios estándar. El contenedor Tauri, el ejecutable Windows y el instalador NSIS están generados.</p><div class="notice"><b>Instalador experimental; aceptación Windows pendiente.</b><br>La compilación y el empaquetado se comprobaron desde Linux. La instalación, los diálogos nativos, el inicio desde Explorer y las asociaciones todavía no se ejecutaron en Windows. La suite completa continúa en desarrollo.</div>']
parts.append(f'<div class="stats"><div class="stat"><b>{counts["passed"]}</b>recorridos de interfaz aprobados</div><div class="stat"><b>{counts["partial"]}</b>recorridos con límites explícitos</div><div class="stat"><b>{len(engine["results"])}</b>pruebas de motor aprobadas</div><div class="stat"><b>4</b>pruebas de archivos Rust aprobadas</div></div>')
parts.append('<p class="muted">Plataforma de prueba: Linux/Chromium, Node/WASM y herramientas independientes. Cero pruebas del contenedor ejecutadas en Windows. Las 3 parciales corresponden a preparación de impresión web, escaneo sin OCR y formulario sin controles.</p><nav><a href="#cambios">Cambios</a><a href="#arquitectura">Arquitectura</a><a href="#modulos">Módulos</a><a href="#pruebas">Pruebas</a><a href="#visuales">Visuales</a><a href="#etapas">Etapas</a><a href="#entrega">Entrega</a></nav>')
parts.append('<section id="cambios"><h2>Qué cambió realmente</h2><table><tr><th>Área</th><th>Versión auditada</th><th>0.2.0 comprobado</th></tr><tr><td>Comentarios</td><td>Gráficos dibujados y notas como páginas adicionales; cero comentarios estándar.</td><td>Text/Highlight estándar con apariencias. Reimportar, editar nota, borrar y guardar sin duplicar ni agregar páginas.</td></tr><tr><td>Unicode</td><td>Caracteres 漢字 🙂 se sustituían por signos de interrogación.</td><td>Contenido Unicode conservado y leído con pypdf; ubicación ensayada con recorte y cuatro rotaciones.</td></tr><tr><td>Archivo cifrado</td><td>Lectura correcta; fallaba exportar anotaciones.</td><td>Derivado W9 AES-256 exportado y reabierto con la misma contraseña.</td></tr><tr><td>Escritorio</td><td>Visor web; sin instalador.</td><td>Backend Tauri/Rust compilado para MSVC e instalador NSIS generado. Uso nativo pendiente de aceptación.</td></tr><tr><td>Iconos</td><td>Dirección visual elegida.</td><td>Pliegue integrado en SVG y recursos ICO multiresolución para programa y archivo PDF. Asociación/icono en Explorer pendientes de prueba.</td></tr></table><p>La copia congelada del visor y la evaluación histórica se mantienen separadas de esta implementación. El reporte anterior sigue documentando el estado previo.</p></section>')
parts.append('<section id="arquitectura"><h2>Arquitectura instalada y base reutilizable</h2><div class="flow"><div class="node"><b>React + PDF.js</b><small>Interfaz, render, texto, navegación y búsqueda conservados.</small></div><div class="node"><b>MuPDF.js / WASM</b><small>Inspeccionar/importar/guardar comentarios en worker cancelable por operación.</small></div><div class="node"><b>Adaptador de plataforma</b><small>Descarga web o IPC binario/diálogos Tauri; los bytes originales se conservan.</small></div><div class="node"><b>Rust / Tauri</b><small>Archivos, guardado de copia, sesiones JSON y eventos de apertura.</small></div></div><p>Se eligió MuPDF en WASM para compartir el motor entre la aplicación de escritorio y el navegador. El enlace C nativo previsto en el primer diseño no se incorporó en esta fase. Las sesiones usan JSON atómico; SQLite queda pendiente. El render todavía depende de PDF.js en la interfaz y la separación completa del dominio seguirá ampliándose.</p><p>Entrada nativa máxima: <b>100 MiB</b>; salida: <b>128 MiB</b>. Se recibe el archivo completo y aún no hay lectura por bloques ni límite duro de memoria WASM. Cada trabajo tiene cancelación y plazo de 90 segundos; se limita el tamaño de los canvas. Esto no acredita rendimiento de archivos de 100 MiB.</p><p>El guardado nativo prepara una copia temporal y confirma su escritura. Rechaza el original y sus alias, y comprueba el destino después del diálogo. Las cuatro pruebas Rust verificaron esa lógica en Linux; quedan fallos de almacenamiento/interrupción y comportamiento Windows por ensayar. Las sesiones y notas locales no están cifradas. La contraseña se mantiene en RAM.</p><h3>Dependencias, licencias y posibles costos</h3><table><tr><th>Componente</th><th>Licencia</th><th>Uso / costo</th></tr>')
for row in dependencies:parts.append('<tr>'+''.join('<td>'+esc(c)+'</td>' for c in row)+'</tr>')
parts.append('</table><p>Los avisos completos y las versiones exactas están en THIRD-PARTY-NOTICES.txt y <a href="dependency-licenses.json">dependency-licenses.json</a>. El instalador incluye LICENSE.txt, avisos e instrucciones de fuente. Necesita Internet para descargar WebView2 si el equipo no lo tiene; después el lector trabaja localmente. No hay publicación del sitio ni actualización automática configurada.</p></section>')
parts.append('<section id="modulos"><h2>Estado actual de los diez módulos</h2><table><tr><th>Módulo / estado</th><th>Disponible o propuesto</th><th>Límites reales</th></tr>')
for name,state,available,limits in modules:parts.append('<tr><td>'+esc(name)+'<br><small>'+esc(state)+'</small></td><td>'+esc(available)+'</td><td>'+esc(limits)+'</td></tr>')
parts.append('</table></section><section id="pruebas"><h2>Resultados y alcance de las pruebas</h2><p>Corpus real: artículo TraceMonkey (14 páginas), manual Emacs (804 páginas / 3,08 MB), escaneo público sin texto y formulario IRS W9 (6 páginas). Se usó además un derivado cifrado controlado del W9. Los archivos restringidos, las estructuras de firma y las cuatro rotaciones son casos de prueba construidos.</p><p>Los cinco PDF anotados se reabrieron con MuPDF y pypdf. Se compararon páginas, texto, hashes de imágenes, valores de campos y bytes decodificados de los streams de contenido originales. Poppler renderizó y extrajo texto de salidas no cifradas. Unicode, borrado de comentarios y conservación de recorte/rotación también se comprobaron.</p><p><b>Límite:</b> todavía falta abrir manualmente esas salidas en Acrobat/Foxit/PDF-XChange bajo Windows. No se ha probado edición del texto original ni eliminación permanente de secretos, porque esas herramientas no existen en el producto.</p><table><tr><th>Recorrido de interfaz</th><th>Resultado</th></tr>')
labels={
 'initial-sample-and-ui':'Carga inicial y lectura', 'real-text-navigation-search-zoom-rotation':'Texto, navegación, búsqueda, zoom y giro de vista', 'annotations-undo-redo-note-export':'Resaltado, nota, historia y exportación estándar', 'local-library-reopen':'Restauración de sesión web', 'original-download-byte-preservation':'Copia original idéntica byte a byte', 'print-preparation-only':'Preparación de impresión web; impresora pendiente', 'real-scanned-pdf-no-ocr':'Escaneo visible; OCR ausente', 'real-acroform-read-not-fill':'W9 estático; completar ausente', 'aes256-password-wrong-correct-encrypted-export':'AES-256 y exportación conservando contraseña', 'password-cancel-preserves-current-document':'Cancelar contraseña conserva documento previo', 'large-real-804-page-document':'Primera/última página del manual de 804 páginas', 'invalid-pdf-is-rejected-without-destroying-current-document':'PDF inválido rechazado; documento previo conservado', 'reopen-standard-edit-unicode-delete-and-save':'Reimportar, editar Unicode y borrar todos los comentarios', 'restricted-document-disables-annotation-tools':'Permisos restringidos bloquean herramientas', 'signature-detection-readonly-without-validity-claim':'Detectar estructura de firma sin afirmar validez', 'privacy-local-requests-no-external-upload':'Solicitudes locales; sin envío de documentos'}
labels.update({'invalid-file-preserves-current-pdf':'PDF inválido rechazado; documento previo conservado','reopen-standard-annotations-and-unicode':'Reimportar, editar Unicode y borrar todos los comentarios','restricted-pdf-disables-annotation-tools':'Permisos restringidos bloquean herramientas','signature-detection-is-read-only-without-validity-claim':'Detectar estructura de firma sin afirmar validez','privacy-transport-during-tests':'Solicitudes locales; sin envío de documentos'})
for r in browser['results']:parts.append('<tr><td>'+esc(labels.get(r['id'],r['id']))+'</td><td class="'+('ok' if r['status']=='passed' else 'partial')+'">'+('Aprobado' if r['status']=='passed' else 'Parcial')+'</td></tr>')
parts.append('</table><p class="web-only"><a href="evidence/browser-results.json">Interfaz: JSON</a> · <a href="evidence/engine-results.json">Motor: JSON</a> · <a href="evidence/interoperability-results.json">Interoperabilidad: JSON</a> · <a href="evidence/corpus-manifest.json">Corpus: origen y SHA-256</a></p><p>El generador de corpus acepta copias ya descargadas y verifica su hash. El manual GNU respondió HTTP 403/503 al intentar descargarlo de nuevo; se verificó la copia de la auditoría. No se actualizan hashes automáticamente ante cambios de edición. Las mediciones del manual corresponden a una sola ejecución Linux y no son un benchmark Windows.</p></section>')
parts.append('<section id="visuales"><h2>Capturas reales y borradores de diseño</h2><h3>Interfaz ejecutada en navegador</h3><p>Las siguientes capturas provienen de las pruebas de la versión actual. El contenedor Windows no se capturó porque todavía no se ejecutó allí.</p>')
for filename,label in [('actual-annotations.png','Notas y resaltados exportados como comentarios estándar'),('actual-large-last-page.png','Página 804 del documento real'),('actual-form-static.png','Formulario visible con campos no interactivos')]:parts.append('<figure class="screen"><a href="evidence/'+filename+'"><img src="evidence/'+filename+'" alt="'+esc(label)+'"></a><figcaption>CAPTURA REAL · '+esc(label)+'</figcaption></figure>')
parts.append('<h3>Iconos implementados · opción 04 «Pliegue»</h3><p>Programa: tile coral con pliegue marfil. Archivo: hoja PDF con la misma marca. Recursos SVG e ICO de varias resoluciones generados e incorporados al instalador; falta comprobar el registro y la visualización del icono de archivo en Explorer.</p><figure class="icons"><img src="designs/12-iconos-elegidos-pliegue.png" alt="Dirección visual elegida para iconos"><figcaption>REFERENCIA APROBADA · Los recursos implementados se encuentran en public/ y assets/pdf-file-icons/ dentro de la fuente.</figcaption></figure><h3>Borradores coherentes para los diez módulos</h3><div class="notice">Estos dibujos muestran flujos propuestos. Sus etiquetas internas se generaron durante la evaluación original; la tabla de estado de esta entrega indica qué subconjunto existe hoy. Un dibujo no acredita implementación.</div>')
for filename,title,flow in drafts:parts.append('<figure class="draft"><h3>BORRADOR · '+esc(title)+'</h3><a href="designs/'+filename+'"><img src="designs/'+filename+'" alt="Borrador '+esc(title)+'"></a><figcaption>'+esc(flow)+'</figcaption></figure>')
parts.append('</section><section id="etapas"><h2>Etapas y pruebas de aceptación</h2><table><tr><th>Etapa / estado</th><th>Condición de aceptación</th></tr>')
